# User Story with Acceptance Criteria (JSON)
{
  "user_story": {
    "id": "US-101",
    "title": "User authentication via email and password",
    "narrative": "As a new user, I want to create an account and log in with my email and password, so that I can access my personalized dashboard.",
    "story_points": 8,
    "priority": "High",
    "acceptance_criteria": [
      {
        "id": "AC1",
        "criterion": "Registration form must validate email format",
        "scenario": "When user enters invalid email → Error message shown"
      },
      {
        "id": "AC2",
        "criterion": "Password must be at least 8 characters with uppercase and numbers",
        "scenario": "When password is weak → Validation error displayed"
      },
      {
        "id": "AC3",
        "criterion": "Account created successfully when all fields valid",
        "scenario": "When form submitted correctly → Account created, redirected to login"
      },
      {
        "id": "AC4",
        "criterion": "Login successful with correct credentials",
        "scenario": "When email and password correct → Logged in, session created"
      },
      {
        "id": "AC5",
        "criterion": "Failed login attempt with helpful error message",
        "scenario": "When credentials incorrect → Clear error, no account enumeration"
      }
    ]
  }
}
